def permitir_ejercicios_al_entrenador(apps, schema_editor):
    """El entrenador puede crear y editar ejercicios (con su imagen).

    Se agrega en la plantilla (gimnasio NULL) y en cada gimnasio existente,
    porque cada gimnasio tiene su propia matriz de permisos. Es idempotente y
    no quita ningún permiso existente.
    """
    Gimnasio = apps.get_model("gym", "Gimnasio")
    Permiso = apps.get_model("gym", "Permiso")
    Recurso = apps.get_model("gym", "Recurso")
    Rol = apps.get_model("gym", "Rol")
    RolPermiso = apps.get_model("gym", "RolPermiso")
    RolRecurso = apps.get_model("gym", "RolRecurso")

    entrenador = Rol.objects.filter(nombre="entrenador", gimnasio__isnull=True).first()
    recurso = Recurso.objects.filter(nombre="ejercicios").first()
    if entrenador is None or recurso is None:
        return
    permisos = list(Permiso.objects.filter(codigo__in=("ejercicios:create", "ejercicios:edit")))
    gimnasios = [None, *Gimnasio.objects.values_list("pk", flat=True)]
    for gimnasio_id in gimnasios:
        RolRecurso.objects.get_or_create(
            rol_id=entrenador.pk, recurso_id=recurso.pk, gimnasio_id=gimnasio_id
        )
        for permiso in permisos:
            RolPermiso.objects.get_or_create(
                rol_id=entrenador.pk, permiso_id=permiso.pk, gimnasio_id=gimnasio_id
            )


